package org.cvp.inventory;
import org.junit.jupiter.api.Test; import java.util.List; import java.util.Optional; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class InventoryControllerTest {
 @Test void preservesCapabilityFields(){var request=new Request("TEST-VEHICLE","MODEL-X",2024,"SG","HYBRID",List.of("maintenance-reminders"));var vehicle=new Vehicle(request.vehicleId(),request,1);assertEquals("MODEL-X",vehicle.modelCode);assertEquals(2024,vehicle.modelYear);assertTrue(vehicle.supportedCapabilities.contains("maintenance-reminders"));}
 @Test void authoritativeUpdateAdvancesRevision(){var first=new Request("TEST-INVENTORY-001","MODEL-X",2024,"SG","HYBRID",List.of("maintenance-reminders"));var updated=new Request("TEST-INVENTORY-001","MODEL-X",2025,"SG","HYBRID",List.of("maintenance-reminders"));var vehicle=new Vehicle(first.vehicleId(),first,1);vehicle.apply(updated,2);assertEquals(2,vehicle.sourceVersion);assertEquals(2025,vehicle.modelYear);}
 @Test void identicalUpdateDoesNotCreateAnotherOutboxIntent(){var request=new Request("TEST-INVENTORY-002","MODEL-X",2024,"SG","HYBRID",List.of("REMOTE_LOCK","REMOTE_CLIMATE"));var vehicle=new Vehicle(request.vehicleId(),request,1);Vehicles vehicles=mock(Vehicles.class);ChangeOutboxes outbox=mock(ChangeOutboxes.class);when(vehicles.findById(request.vehicleId())).thenReturn(Optional.of(vehicle));new InventoryChanges(vehicles,outbox).update(request);verify(vehicles,never()).save(any());verify(outbox,never()).save(any());assertEquals(1,vehicle.sourceVersion);}
 @Test void changedUpdateAdvancesVersionAndWritesOneOutboxIntent(){var original=new Request("TEST-INVENTORY-003","MODEL-X",2024,"SG","HYBRID",List.of("REMOTE_LOCK"));var changed=new Request("TEST-INVENTORY-003","MODEL-X",2024,"SG","HYBRID",List.of("REMOTE_LOCK","REMOTE_HORN"));var vehicle=new Vehicle(original.vehicleId(),original,1);Vehicles vehicles=mock(Vehicles.class);ChangeOutboxes outbox=mock(ChangeOutboxes.class);when(vehicles.findById(changed.vehicleId())).thenReturn(Optional.of(vehicle));when(vehicles.save(any())).thenAnswer(i->i.getArgument(0));new InventoryChanges(vehicles,outbox).update(changed);assertEquals(2,vehicle.sourceVersion);verify(vehicles).save(vehicle);verify(outbox,times(1)).save(any(ChangeOutbox.class));}
}
